<script setup lang="ts">import {ref,computed} from 'vue';import PageTitle from '../components/common/PageTitle.vue';import Notice from '../components/common/Notice.vue';import Status from '../components/common/Status.vue';import Table from '../components/common/Table.vue';import Empty from '../components/common/Empty.vue';import {trainingApi} from '../api/training';import {useTask} from '../hooks/useTask';import {fmt} from '../utils/format';const p=defineProps<{studies:any[];traces:any[];profiles:any[];jobs:any[];user:any;reloadTraining:()=>Promise<void>}>();const id=ref(0),pid=ref(0),name=ref('页面约束训练 '+new Date().toLocaleTimeString()),maxIterations=ref(10),batchSize=ref(8),tolerance=ref(0.000001),selected=ref<number[]|null>(null),detailId=ref(0),detail=ref<any>(null),task=useTask();const study=computed(()=>p.studies.find(s=>s.id===(id.value||p.studies[0]?.id)));const rows=computed(()=>p.traces.filter(t=>t.study_id===study.value?.id));const available=computed(()=>p.profiles.filter(m=>m.study_id===study.value?.id));const profile=computed(()=>available.value.find(m=>m.id===pid.value)||available.value[0]);const ids=computed(()=>selected.value===null?rows.value.map(t=>t.id):selected.value);const current=computed(()=>p.jobs.find(j=>j.id===detailId.value)||p.jobs[0]);function toggle(t:number){selected.value=ids.value.includes(t)?ids.value.filter(v=>v!==t):[...ids.value,t]}async function loadDetail(jobId:number){detailId.value=jobId;try{detail.value=await trainingApi.detail(jobId)}catch(e){detail.value=null}}async function submit(){await task.act(async()=>{const job=await trainingApi.create({study_id:study.value.id,profile_id:profile.value.id,name:name.value,trace_ids:ids.value,max_iterations:maxIterations.value,batch_size:batchSize.value,tolerance:tolerance.value});await p.reloadTraining();await loadDetail(job.id)},'观测与初始模型已冻结，训练已分批排队')}async function refresh(){await p.reloadTraining();if(detailId.value)await loadDetail(detailId.value)}const detailJob=computed(()=>detail.value||current.value);</script><template><PageTitle index="04" title="页面约束训练：多条独立轨迹一起校准初态、转移与发射。" description="Baum-Welch 期望计数按批次落库；预设零保持零，无期望计数的行保留原值；逐轮展示总对数似然，下降的更新不发布。"/><label>训练研究<select :value="study?.id||0" @change="id=Number(($event.target as HTMLSelectElement).value)"><option v-for="s in studies" :key="s.id" :value="s.id">{{s.name}}</option></select></label><div class="config-layout"><form class="input-panel" @submit.prevent="submit"><small>01 / CONSTRAINED BATCH TRAINING</small><h2>建立页面约束训练</h2><label>训练名称<input v-model="name" required/></label><label>初始模型版本（冻结）<select :value="profile?.id||0" @change="pid=Number(($event.target as HTMLSelectElement).value)"><option v-for="m in available" :key="m.id" :value="m.id">{{m.name}} / {{m.version}}</option></select></label><div class="field-pair"><label>最大轮数<input v-model.number="maxIterations" type="number" min="1" max="100" required/></label><label>每批轨迹数<input v-model.number="batchSize" type="number" min="1" max="60" required/></label></div><label>收敛容差<input v-model.number="tolerance" type="number" min="0" step="0.0000001" required/></label><p>已选 {{ids.length}} 条独立轨迹；提交时冻结初始 π/A/B 与观测快照，之后修订源记录不影响训练。</p><div class="trace-picker"><label v-for="t in rows" :key="t.id"><input type="checkbox" :checked="ids.includes(t.id)" @change="toggle(t.id)" :aria-label="'选择-'+t.reference"/><span>{{t.reference}}<small>{{t.tokens.length}}码 / {{t.tokens.slice(0,8).join(' ')}}</small></span></label></div><button v-if="user.role!=='viewer'" class="primary" :disabled="task.state.busy||!profile||ids.length<1">排队分批约束训练 →</button><p v-else>观察员只读，不能发起训练。</p></form><section class="selection-panel"><small>02 / ROUND-BY-ROUND TOTAL LOG-LIKELIHOOD</small><h2>逐轮总对数似然与批次进度</h2><template v-if="detailJob"><p><strong>{{detailJob.name}}</strong>　<Status :value="detailJob.status"/>　轮次 {{detailJob.current_iteration}}/{{detailJob.max_iterations}}　累计批次 {{detailJob.total_batches}}　投递次数 {{detailJob.attempts}}</p><p v-if="detailJob.error" class="copper">{{detailJob.error}}</p><Table :headers="['轮','批次数/码数','轮前总logL','候选总logL','是否发布','原因']"><tr v-for="log in detailJob.iteration_logs" :key="log.iteration"><td>{{log.iteration}}</td><td>{{log.batch_count}} / {{log.token_count}}</td><td>{{fmt(log.previous_log_likelihood,6)}}</td><td>{{fmt(log.new_log_likelihood,6)}}</td><td>{{log.accepted?'发布':'拒绝（不下降才发布）'}}</td><td>{{log.reason==='increase'?'似然上升':'似然未上升，保留旧参数'}}</td></tr></Table><details v-if="detailJob.batches?.length" class="provenance"><summary>批次写入明细（崩溃恢复不重算已保存批次）</summary><Table :headers="['轮','批','状态','轨迹数','码数','批次logL','写入者']"><tr v-for="b in detailJob.batches" :key="b.id"><td>{{b.iteration+1}}</td><td>{{b.batch_index+1}}</td><td>{{b.status==='saved'?'已保存':'待处理'}}</td><td>{{b.trace_ids.length}}</td><td>{{b.token_count??'—'}}</td><td>{{b.log_likelihood===null?'—':fmt(b.log_likelihood,6)}}</td><td>{{b.written_by||'—'}}</td></tr></Table></details><div v-if="detailJob.published_profile_id" class="boundary-note"><strong>已发布唯一可推断模型版本 #{{detailJob.published_profile_id}}</strong><p>训练只产出这一个模型版本，可在“固定模型推断”页直接选用；旧推断与已批准核对说明保持不变。</p></div></template><Empty v-else title="还没有约束训练任务" help="选择初始固定模型与多条独立轨迹后排队；训练全程保留结构零，不设概率地板。"/></section></div><Notice v-bind="task.state"/><section class="section"><div class="section-head"><h2>训练任务归档</h2><button type="button" @click="refresh">刷新进度 ↗</button></div><Table :headers="['训练任务','状态','轮次/批次','当前总logL','发布模型','明细']"><tr v-for="j in jobs" :key="j.id"><td><strong>{{j.name}}</strong><small>#{{j.id}} / {{j.profile_snapshot?.name}}</small></td><td><Status :value="j.status"/><small v-if="j.error" class="copper">{{j.error}}</small></td><td>{{j.current_iteration}}/{{j.max_iterations}} / {{j.total_batches}}</td><td>{{j.total_log_likelihood===null?'—':fmt(j.total_log_likelihood,5)}}</td><td>{{j.published_profile_id?('版本#'+j.published_profile_id):'未发布'}}</td><td><button @click="loadDetail(j.id)">批次与逐轮明细 ↗</button></td></tr></Table></section></template>
